function expand(course) {
 const lessons=course.sections.flatMap(s=>s.topics.flatMap(t=>t.lessons||[t.lesson].filter(Boolean)));
 for(const [slug,blocks] of Object.entries(additions)) {
  const lesson=lessons.find(l=>l.slug===slug);
  if(!lesson)throw new Error('Missing lesson: '+slug);
  if(lesson.blocks.some(b=>b.type==='heading'&&b.content.text===blocks[0].content.text))continue;
  const index=lesson.blocks.findIndex(b=>b.type==='summary');
  if(index<0)throw new Error('Missing summary: '+slug);
  lesson.blocks.splice(index,0,...structuredClone(blocks));
  lesson.contentStatus='review';
 }
 const membrane=lessons.find(l=>l.slug==='bio-cell-2-lesson-2');
 for(const b of membrane.blocks)if(b.content.text)b.content.text=b.content.text.replace('хвосты скрываются друг от друга внутри бислоя','хвосты обращены друг к другу внутрь бислоя и изолированы от воды');
 const pedigree=lessons.find(l=>l.slug==='bio-genetics-2-lesson-3');
 for(const b of pedigree.blocks)if(b.type==='table')for(const row of b.content.rows){
  if(row[0]==='есть отец→сын'){row[0]='отец и сын имеют одинаковый признак';row[1]='само по себе не исключает X-сцепленную модель: сын мог получить аллель от матери';}
 }
 return course;
}
if(require.main===module){
 const file=path.resolve(__dirname,'../content/biology/course.json');
 const course=JSON.parse(fs.readFileSync(file,'utf8'));
 fs.writeFileSync(file,JSON.stringify(expand(course),null,2)+'\n');
 console.log('Exam core supplements: '+Object.keys(additions).length+' lessons.');
}
module.exports={expand,additions};
